    comparisons: [{ title: 'Tanrı-evren ilişkisi', columns: ['Teizm', 'Deizm', 'Panteizm'], rows: [{ label: 'Yaratma/ilişki', values: ['Yaratır ve ilişki sürer', 'Yaratır, müdahale etmez', 'Tanrı ve evren bir bütündür'] }, { label: 'Aşkınlık', values: ['Evreni aşar', 'Evreni aşar', 'Evrene içkindir'] }], insight: '“Tanrı var” ortak cümlesi yetmez; evrenle ilişkisinin nasıl kurulduğuna bak.' }, { title: 'Ateizm ve agnostisizm', columns: ['Ateizm', 'Agnostisizm'], rows: [{ label: 'İddia', values: ['Tanrı yoktur', 'Varlığı/yokluğu bilinemez'] }, { label: 'Alan', values: ['Varlık', 'Bilgi'] }], insight: 'Biri ontolojik, diğeri epistemolojik iddiadır.' }],
    philosophers: [{ name: 'Thomas Aquinas', view: 'Evrenin hareket, neden ve düzeninden ilk nedene ulaşan kanıtlar kurar.', logic: 'Bağımlı nedenler zincirini zorunlu ilk nedende temellendirmek.', clues: ['ilk neden', 'düzen', 'hareket'], contrast: 'Tanrı kanıtlarının aklın sınırını aştığını savunan eleştiriler.' }, { name: 'Spinoza', view: 'Tanrı ile doğayı tek sonsuz tözün ifadeleri olarak düşünür.', logic: 'Tanrı ve evreni iki ayrı varlık saymamak.', clues: ['Tanrı ya da Doğa', 'tek töz', 'içkinlik'], contrast: 'Tanrıyı evrenden ayrı gören teizm ve deizm.' }],
